232	/// `~/.leviathan/memory.db`, or under `LEVIATHAN_HOME` when set.
233	pub fn default_path() -> PathBuf {
234	    if let Some(home) = std::env::var_os("LEVIATHAN_HOME").filter(|v| !v.is_empty()) {
235	        return PathBuf::from(home).join("memory.db");
236	    }
237	    match home_dir() {
238	        Some(home) => home.join(".leviathan").join("memory.db"),
239	        None => PathBuf::from("leviathan-memory.db"),
240	    }
241	}
242	
243	fn home_dir() -> Option<PathBuf> {
244	    ["HOME", "USERPROFILE"]
245	        .iter()
246	        .find_map(|v| std::env::var_os(v).filter(|h| !h.is_empty()))
247	        .map(PathBuf::from)
248	}
