250	/// Expand a leading `~/` to the home directory.
251	pub fn expand_home(path: &str) -> PathBuf {
252	    match (path.strip_prefix("~/").or_else(|| path.strip_prefix("~\\")), home_dir()) {
253	        (Some(rest), Some(home)) => home.join(rest),
254	        _ if path == "~" => home_dir().unwrap_or_else(|| PathBuf::from(path)),
255	        _ => PathBuf::from(path),
256	    }
257	}
