297	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
298	#[serde(rename_all = "snake_case")]
299	pub enum State {
300	    Current,
301	    Superseded,
302	    Forgotten,
303	    Expired,
304	}
305	
306	impl MemoryRow {
307	    pub fn state(&self, now: &str) -> State {
308	        if self.deleted_at.is_some() {
309	            State::Forgotten
310	        } else if self.valid_to.is_some() {
311	            State::Superseded
312	        } else if self.expires_at.as_deref().is_some_and(|e| e <= now) {
313	            State::Expired
314	        } else {
315	            State::Current
316	        }
317	    }
318	
319	    /// One compact line: what agents read.
320	    pub fn line(&self, now: &str, show_ns: bool) -> String {
321	        let mut head = format!("[{}", self.kind.as_str());
322	        match self.state(now) {
323	            State::Current => {}
324	            State::Superseded => {
325	                head.push_str(&format!(
326	                    " · SUPERSEDED {}",
327	                    day(self.valid_to.as_deref().unwrap_or_default())
328	                ));
329	            }
330	            State::Forgotten => {
331	                head.push_str(&format!(
332	                    " · FORGOTTEN {}",
333	                    day(self.deleted_at.as_deref().unwrap_or_default())
334	                ));
335	            }
336	            State::Expired => head.push_str(" · EXPIRED"),
337	        }
338	        head.push(']');
339	        let mut out = head;
340	        if show_ns {
341	            out.push_str(&format!(" {}:", self.ns));
342	        }
343	        match (&self.subject, &self.key) {
344	            (Some(s), Some(k)) => out.push_str(&format!(" {s} · {k}:")),
345	            (Some(s), None) => out.push_str(&format!(" {s}:")),
346	            (None, Some(k)) => out.push_str(&format!(" {k}:")),
347	            (None, None) => {}
348	        }
349	        out.push(' ');
350	        out.push_str(&self.text);
351	        let mut meta = vec![day(&self.valid_from).to_string()];
352	        if let Some(s) = &self.source {
353	            meta.push(s.clone());
354	        }
355	        if self.pinned {
356	            meta.push("pinned".into());
357	        }
358	        if !self.refs.is_empty() {
359	            meta.push(format!("refs {}", self.refs.join(", ")));
360	        }
361	        meta.push(self.id.clone());
362	        out.push_str(&format!(" ({})", meta.join(" · ")));
363	        out
364	    }
365	}
