371	fn row(r: &Row<'_>) -> rusqlite::Result<MemoryRow> {
372	    let kind: String = r.get(2)?;
373	    let tags: String = r.get(6)?;
374	    let refs: String = r.get(10)?;
375	    Ok(MemoryRow {
376	        id: r.get(0)?,
377	        ns: r.get(1)?,
378	        kind: Kind::parse(&kind).unwrap_or(Kind::Note),
379	        subject: r.get(3)?,
380	        key: r.get(4)?,
381	        text: r.get(5)?,
382	        tags: tags.split_whitespace().map(str::to_string).collect(),
383	        importance: r.get::<_, i64>(7)?.clamp(1, 5) as u8,
384	        confidence: r.get(8)?,
385	        source: r.get(9)?,
386	        refs: serde_json::from_str(&refs).unwrap_or_default(),
387	        pinned: r.get(11)?,
388	        created_at: r.get(12)?,
389	        updated_at: r.get(13)?,
390	        valid_from: r.get(14)?,
391	        valid_to: r.get(15)?,
392	        superseded_by: r.get(16)?,
393	        expires_at: r.get(17)?,
394	        deleted_at: r.get(18)?,
395	        recall_count: r.get(19)?,
396	        last_recalled_at: r.get(20)?,
397	    })
398	}
