470	pub struct Memory {
471	    conn: Connection,
472	    path: PathBuf,
473	    pub settings: Settings,
474	}
475	
476	pub(crate) fn now() -> String {
477	    crate::now_rfc3339()
478	}
479	
480	impl Memory {
481	    /// Open a memory database, creating it (and its directory) on first use.
482	    pub fn open(path: &Path, settings: Settings) -> Result<Self> {
483	        let fresh = !path.exists();
484	        if fresh && let Some(dir) = path.parent().filter(|d| !d.as_os_str().is_empty()) {
485	            std::fs::create_dir_all(dir).with_context(|| format!("create {}", dir.display()))?;
486	        }
487	        let mut conn = Connection::open(path).with_context(|| format!("open memory {}", path.display()))?;
488	        conn.busy_timeout(std::time::Duration::from_secs(10))?;
489	        let has_meta: bool = conn.query_row(
490	            "SELECT EXISTS (SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'meta')",
491	            [],
492	            |r| r.get(0),
493	        )?;
494	        if has_meta {
495	            let get = |k: &str| -> Result<Option<String>> {
496	                Ok(conn.query_row("SELECT value FROM meta WHERE key = ?1", [k], |r| r.get(0)).optional()?)
497	            };
498	            if get("kind")?.as_deref() != Some(KIND_TAG) {
499	                bail!(
500	                    "{} is not a Leviathan memory database (is it a data index? pass that as --index)",
501	                    path.display()
502	                );
503	            }
504	            let version = get("schema_version")?.unwrap_or_default();
505	            if version != SCHEMA_VERSION {
506	                bail!(
507	                    "memory {} has schema {version:?}; this build reads {SCHEMA_VERSION}. Export it with the version that wrote it",
508	                    path.display()
509	                );
510	            }
511	        } else {
512	            let tables: i64 = conn.query_row("SELECT COUNT(*) FROM sqlite_master", [], |r| r.get(0))?;
513	            if tables > 0 {
514	                bail!("{} is an SQLite database but not a Leviathan memory database", path.display());
515	            }
516	            conn.pragma_update_and_check(None, "journal_mode", "WAL", |r| r.get::<_, String>(0))?;
517	            let tx = conn.transaction()?;
518	            tx.execute_batch(SCHEMA)?;
519	            let created = now();
520	            for (k, v) in
521	                [("kind", KIND_TAG), ("schema_version", SCHEMA_VERSION), ("created_at", created.as_str())]
522	            {
523	                tx.execute("INSERT INTO meta (key, value) VALUES (?1, ?2)", params![k, v])?;
524	            }
525	            tx.commit()?;
526	            restrict_permissions(path);
527	        }
528	        conn.pragma_update(None, "synchronous", "NORMAL")?;
529	        Ok(Self { conn, path: path.to_path_buf(), settings })
530	    }
531	
532	    pub fn path(&self) -> &Path {
533	        &self.path
534	    }
535	
536	    fn write_tx(&mut self) -> Result<rusqlite::Transaction<'_>> {
537	        Ok(self.conn.transaction_with_behavior(TransactionBehavior::Immediate)?)
538	    }
539	
540	    /// Namespaces to read: an explicit comma list, `*` for every namespace,
541	    /// or the configured `read` list.
542	    pub fn read_namespaces(&self, ns: Option<&str>) -> Result<Vec<String>> {
543	        let Some(raw) = ns.map(str::trim).filter(|s| !s.is_empty()) else {
544	            return Ok(self.settings.read.clone());
545	        };
546	        if raw == "*" {
547	            let mut stmt = self.conn.prepare_cached("SELECT DISTINCT ns FROM memories ORDER BY ns")?;
548	            let all = stmt.query_map([], |r| r.get(0))?.collect::<rusqlite::Result<Vec<String>>>()?;
549	            return Ok(if all.is_empty() { self.settings.read.clone() } else { all });
550	        }
551	        raw.split(',').map(|n| guard::namespace(n).map_err(Into::into)).collect()
552	    }
553	
554	    pub fn get(&self, id: &str) -> Result<Option<MemoryRow>> {
555	        get_row(&self.conn, id)
556	    }
557	
558	    /// Every version of a slot (or of the memory with this id), oldest first.
559	    pub fn history(
560	        &self,
561	        id: Option<&str>,
562	        subject: Option<&str>,
563	        key: Option<&str>,
564	        ns: Option<&str>,
565	    ) -> Result<Vec<MemoryRow>> {
566	        let (ns, subject_norm, key) = match (id, key) {
567	            (Some(id), _) => {
568	                let m = self.get(id)?.with_context(|| format!("no memory with id {id:?}"))?;
569	                match m.key.clone() {
570	                    Some(k) => {
571	                        (m.ns.clone(), m.subject.as_deref().map(normalize_name).unwrap_or_default(), k)
572	                    }
573	                    None => return Ok(vec![m]),
574	                }
575	            }
576	            (None, Some(k)) => {
577	                let ns = guard::namespace(ns.unwrap_or(&self.settings.namespace))?;
578	                let norm = match subject {
579	                    Some(s) => resolve_alias(&self.conn, &ns, &normalize_name(s))?,
580	                    None => String::new(),
581	                };
582	                (ns, norm, guard::key(k)?)
583	            }
584	            _ => bail!("pass a memory id, or --key (with --subject when the slot has one)"),
585	        };
586	        let mut stmt = self.conn.prepare_cached(&format!(
587	            "SELECT {COLUMNS} FROM memories WHERE ns = ?1 AND subject_norm = ?2 AND key = ?3 ORDER BY valid_from, rowid"
588	        ))?;
589	        Ok(stmt.query_map(params![ns, subject_norm, key], row)?.collect::<rusqlite::Result<_>>()?)
590	    }
