667	    /// Every row, history included, as JSON lines. Returns the row count.
668	    pub fn export(&self, out: &mut impl Write) -> Result<u64> {
669	        let mut stmt = self.conn.prepare(&format!("SELECT {COLUMNS} FROM memories ORDER BY rowid"))?;
670	        let mut n = 0;
671	        for m in stmt.query_map([], row)? {
672	            serde_json::to_writer(&mut *out, &m?)?;
673	            out.write_all(b"\n")?;
674	            n += 1;
675	        }
676	        Ok(n)
